import { gql } from '@apollo/client';

export interface SlideThumbnail {
  pageId: string;
  num: number;
  thumbUrl: string | null;
}

export interface SlideThumbnailsSubscriptionResponse {
  pres_page: SlideThumbnail[];
}

// pres_page is only readable by the presenter, which is the only user that
// sees the presentation toolbar. Thumbnails are generated by bbb-web at upload
// time (ThumbnailCreatorImp) and their URL is stored in urlsJson.thumb.
export const SLIDE_THUMBNAILS_SUBSCRIPTION = gql`
  subscription SlideThumbnails($presentationId: String!) {
    pres_page(
      where: { presentationId: { _eq: $presentationId } }
      order_by: { num: asc }
    ) {
      pageId
      num
      thumbUrl: urlsJson(path: "$.thumb")
    }
  }
`;

export default SLIDE_THUMBNAILS_SUBSCRIPTION;
